parameters.text:
=You sort incoming emails for Pink City Trails, a travel agency in Jaipur.
Read the email below. Reply with ONLY a JSON object, with no other text and no code fences, in exactly this shape:
{"summary": "one sentence in English, under 25 words", "label": "booking"}

The label must be exactly one of these words: booking, complaint, refund, spam, other.
- booking: a new booking, or a change to an existing booking
- complaint: unhappy with a service already received
- refund: asking for money back
- spam: unwanted marketing, scams or phishing
- other: anything else

From: {{ $json.from }}
Subject: {{ $json.subject }}
Body:
{{ $json.body }}

parameters.jsCode:
// Checks each AI reply before it goes to the sheet.
// It reads the JSON, keeps only allowed labels, and marks anything odd for a person to review.
const allowed = ['booking', 'complaint', 'refund', 'spam', 'other'];
const emails = $('Sample emails').all();   // change this name if you swap in a Gmail trigger

return $input.all().map((item, i) => {
  const email = emails[i] ? emails[i].json : {};
  const raw = item.json.text !== undefined ? item.json.text : item.json;
  let data = {};
  let problem = '';

  if (typeof raw === 'string') {
    const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
    try {
      data = JSON.parse(cleaned);
    } catch (error) {
      problem = 'AI reply was not valid JSON';
    }
  } else {
    data = raw;
  }

  let label = String(data.label || '').toLowerCase().trim();
  if (!problem && !allowed.includes(label)) {
    problem = 'unknown label: ' + label;
  }
  if (problem) {
    label = 'needs review';
  }

  return {
    json: {
      received: email.received || '',
      from: email.from || '',
      subject: email.subject || '',
      summary: data.summary || '',
      label: label,
      check: problem || 'ok',
    },
  };
});
